//! Mirror-aware URL construction and rewriting.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{PoisonError, RwLock};

use crate::error::MdtError;
use crate::mirror::Mirror;

// Provider endpoint-URL and rewrite tables, generated by the `providers!` proc macro from
// `providers.compile.toml` (the MDT analogue of `rust-i18n`'s `i18n!`).
mdt_macros::providers!();

/// Runtime provider overrides, loaded lazily from `providers.runtime.toml` (or the path in
/// `MDT_RUNTIME_PROVIDERS`). Consulted before the compile-time static table for `Mirror::Custom`.
///
/// Deliberately **not** a `OnceLock`: a `OnceLock` caches a *failed* load forever, so a launcher
/// that fixes its `providers.runtime.toml` would have to be restarted before mirrors worked again.
/// Here [`reload_runtime_providers`] replaces the table — and clears the recorded error — at any
/// time, while the lazy path still pays the parse cost only once.
static RUNTIME_PROVIDERS: RwLock<Option<RuntimeProviders>> = RwLock::new(None);

/// The loaded runtime provider table, plus why the last load failed (if it did).
struct RuntimeProviders {
    providers: HashMap<String, toml::Table>,
    /// Why the most recent load failed; `None` when the overrides loaded cleanly or are absent.
    error: Option<String>,
}

impl RuntimeProviders {
    fn empty() -> Self {
        Self {
            providers: HashMap::new(),
            error: None,
        }
    }
}

/// Where the runtime override file lives, if one is configured.
fn runtime_providers_path() -> Option<PathBuf> {
    std::env::var("MDT_RUNTIME_PROVIDERS")
        .ok()
        .map(PathBuf::from)
        .or_else(|| {
            let candidate = Path::new("providers.runtime.toml");
            candidate.exists().then(|| candidate.to_path_buf())
        })
}

/// Run `f` against the loaded runtime providers, loading them on first use.
fn with_runtime_providers<R>(f: impl FnOnce(&HashMap<String, toml::Table>) -> R) -> R {
    with_runtime_state(|state| f(&state.providers))
}

/// Run `f` against the loaded runtime state, loading it on first use.
fn with_runtime_state<R>(f: impl FnOnce(&RuntimeProviders) -> R) -> R {
    // Fast path: already initialized.
    {
        let guard = RUNTIME_PROVIDERS
            .read()
            .unwrap_or_else(PoisonError::into_inner);
        if let Some(state) = guard.as_ref() {
            return f(state);
        }
    }

    // First use (or after a failed load): read the file outside the lock, then publish. A failed
    // load is remembered together with its reason, so a broken file is not re-parsed on every URL.
    let loaded = read_runtime_providers().0;
    {
        let mut guard = RUNTIME_PROVIDERS
            .write()
            .unwrap_or_else(PoisonError::into_inner);
        // Another thread may have initialized it while we were reading the file.
        guard.get_or_insert(loaded);
    }
    let guard = RUNTIME_PROVIDERS
        .read()
        .unwrap_or_else(PoisonError::into_inner);
    let state = guard
        .as_ref()
        .expect("runtime providers were just initialized");
    f(state)
}

/// Reload the runtime provider overrides.
///
/// Call this after writing or editing `providers.runtime.toml` (or the file named by
/// `MDT_RUNTIME_PROVIDERS`) so a long-lived process — a game launcher, a daemon — picks the new
/// mirrors up without restarting. A failed reload clears the previously loaded overrides and is
/// returned as an error, so the caller knows it is back on the compiled-in table.
///
/// # Errors
///
/// [`MdtError::InvalidProviderConfig`] if the file cannot be read or parsed. This does not poison
/// later calls: fix the file and call this again.
pub fn reload_runtime_providers() -> Result<(), MdtError> {
    let (loaded, error) = read_runtime_providers();
    {
        let mut guard = RUNTIME_PROVIDERS
            .write()
            .unwrap_or_else(PoisonError::into_inner);
        *guard = Some(loaded);
    }
    match error {
        Some(e) => Err(e),
        None => Ok(()),
    }
}

/// Why the most recent runtime-provider load failed, if it did.
///
/// `None` when the overrides loaded cleanly or no file was configured. Together with
/// [`reload_runtime_providers`], this is how a long-lived launcher notices a broken config: the URL
/// rewriting layer has no reporter of its own, so the failure is exposed as data instead of being
/// printed to stderr.
#[must_use]
pub fn runtime_providers_error() -> Option<String> {
    with_runtime_state(|state| state.error.clone())
}

/// Read the runtime overrides, returning the state to cache and the error, if any.
fn read_runtime_providers() -> (RuntimeProviders, Option<MdtError>) {
    let Some(path) = runtime_providers_path() else {
        return (RuntimeProviders::empty(), None);
    };
    match parse_runtime_providers(&path) {
        Ok(providers) => (
            RuntimeProviders {
                providers,
                error: None,
            },
            None,
        ),
        Err(e) => (
            RuntimeProviders {
                providers: HashMap::new(),
                error: Some(e.to_string()),
            },
            Some(e),
        ),
    }
}

/// Read and parse one runtime provider override file.
///
/// Parsed as a **document** (`toml::from_str::<toml::Table>`), not via `str::parse::<toml::Value>`:
/// `Value`'s `FromStr` parses a single TOML *value* (`toml-1.1.8/src/value.rs:397`), so every real
/// `[section]` file failed with "unexpected content, expected nothing" and the override table was
/// silently left empty — a bug this rewrite fixes along with the `OnceLock`.
fn parse_runtime_providers(path: &Path) -> Result<HashMap<String, toml::Table>, MdtError> {
    let invalid = |reason: String| MdtError::InvalidProviderConfig {
        path: path.display().to_string(),
        reason,
    };

    let text = std::fs::read_to_string(path).map_err(|e| invalid(e.to_string()))?;
    let table: toml::Table = toml::from_str(&text).map_err(|e| invalid(e.to_string()))?;
    Ok(table
        .iter()
        .filter_map(|(name, section)| section.as_table().cloned().map(|t| (name.clone(), t)))
        .collect())
}

/// Extract ordered `[[name.{key}]]` `(from, to)` pairs from a runtime provider table.
fn runtime_rewrite_rules(table: &toml::Table, key: &str) -> Vec<(String, String)> {
    let Some(value) = table.get(key) else {
        return Vec::new();
    };
    let Some(array) = value.as_array() else {
        return Vec::new();
    };
    array
        .iter()
        .filter_map(|item| {
            let t = item.as_table()?;
            let from = t.get("from")?.as_str()?;
            let to = t.get("to")?.as_str()?;
            Some((from.to_string(), to.to_string()))
        })
        .collect()
}

/// Whether `s` begins with a character that already separates a URL's parts.
fn starts_with_separator(s: &str) -> bool {
    matches!(s.chars().next(), Some('/' | '\\' | '?' | '#' | ':'))
}

/// Whether `s` ends where a URL's next part would start (`/`, `?`, `#`, `:`) or already carries a
/// separator (`=`, as in `?mirror=`).
fn ends_with_separator(s: &str) -> bool {
    matches!(s.chars().last(), Some('/' | '\\' | '?' | '#' | ':' | '='))
}

/// Rewrite `url` only when it starts with `from`, replacing exactly that prefix with `to`.
///
/// `String::replace` is unusable here: a rule like `from = "library"` corrupts every occurrence
/// inside a path, and even a domain-only rule rewrites a host that merely *contains* it
/// (`https://piston-meta.mojang.com.evil/x`) or a URL embedded in someone else's query string.
///
/// Two extra guards:
///
/// * the prefix must end on a URL boundary, so `…mojang.com` cannot swallow `…mojang.com.evil`;
/// * the join keeps exactly one separator — no `//` when `to` already ends with `/`, and no
///   `mavencom/x.jar` glue when `from` ended with a separator but `to` does not.
fn rewrite_prefix(url: &str, from: &str, to: &str) -> Option<String> {
    if from.is_empty() {
        return None;
    }
    let suffix = url.strip_prefix(from)?;
    if !suffix.is_empty() && !starts_with_separator(suffix) && !ends_with_separator(from) {
        return None;
    }

    let base = to.trim_end_matches('/');
    if suffix.is_empty() {
        Some(base.to_string())
    } else if starts_with_separator(suffix) {
        Some(format!("{base}{suffix}"))
    } else {
        Some(format!("{base}/{suffix}"))
    }
}

/// Apply the first matching prefix rule, or `None` when nothing matches.
fn rewrite_url<'a, I>(url: &str, rules: I) -> Option<String>
where
    I: IntoIterator<Item = (&'a str, &'a str)>,
{
    rules
        .into_iter()
        .find_map(|(from, to)| rewrite_prefix(url, from, to))
}

/// The host of a URL-ish string: `https://user@host:8443/x` → `host`, `maven.quiltmc.org` → as-is.
fn url_host(value: &str) -> &str {
    let rest = value.split_once("://").map_or(value, |(_, rest)| rest);
    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    let authority = authority
        .rsplit_once('@')
        .map_or(authority, |(_, host)| host);
    if let Some(after_bracket) = authority.strip_prefix('[') {
        // IPv6 literal: keep `[…]` and drop any trailing `:port`.
        return after_bracket
            .split_once(']')
            .map_or(authority, |(inner, _)| &authority[..inner.len() + 2]);
    }
    authority.split(':').next().unwrap_or(authority)
}

/// Whether `url`'s host is `excluded` or a subdomain of it.
///
/// `maven_exclude` entries name hosts (`maven.quiltmc.org`), so a `contains` check is both too
/// broad (a *path* or query holding that text would exclude an unrelated URL) and too narrow (it
/// would miss a scheme-prefixed entry). Comparing the parsed authority is exact, and a subdomain
/// counts because the host is the same registry.
fn host_is_excluded(url: &str, excluded: &str) -> bool {
    let excluded_host = url_host(excluded.trim());
    if excluded_host.is_empty() {
        return false;
    }
    let host = url_host(url);
    host.eq_ignore_ascii_case(excluded_host)
        || host
            .to_ascii_lowercase()
            .ends_with(&format!(".{}", excluded_host.to_ascii_lowercase()))
}

/// Extract a `name.{key} = [...]` string list from a runtime provider table.
fn runtime_string_list(table: &toml::Table, key: &str) -> Vec<String> {
    let Some(value) = table.get(key) else {
        return Vec::new();
    };
    let Some(array) = value.as_array() else {
        return Vec::new();
    };
    array
        .iter()
        .filter_map(|item| item.as_str().map(str::to_string))
        .collect()
}

/// The set of endpoints and download base URLs for the active mirror.
#[derive(Debug, Clone)]
pub struct ManifestUrls {
    // ===== manifest (metadata) endpoints =====
    pub minecraft: String,
    pub fabric: String,

    // ===== loader download base URLs =====
    pub fabric_maven: String,

    // ===== metadata bases used to join profile sub-endpoints =====
    pub fabric_meta: String,
}

impl ManifestUrls {
    /// Build the endpoint table for the given mirror, or fail if its provider is unknown.
    ///
    /// The URLs are sourced from `providers.compile.toml` (compiled in by the `providers!` proc
    /// macro). Returns [`MdtError::UnknownProvider`] when the mirror's provider name is not
    /// declared in that file.
    pub fn try_new(mirror: &Mirror) -> Result<Self, MdtError> {
        let name = mirror.provider_name();

        // A custom mirror may be overridden at runtime before falling back to the compiled table.
        if let Some(table) = Self::runtime_table(mirror) {
            return Self::from_runtime(name, &table);
        }

        let p = provider_urls(name).ok_or_else(|| MdtError::UnknownProvider(name.to_string()))?;
        Ok(Self {
            minecraft: p.minecraft.to_string(),
            fabric: p.fabric.to_string(),

            fabric_maven: p.fabric_maven.to_string(),

            fabric_meta: p.fabric_meta.to_string(),
        })
    }

    /// The runtime override table for a custom mirror, if one was loaded.
    ///
    /// Cloned rather than borrowed: the table lives behind an `RwLock` that
    /// [`reload_runtime_providers`] may replace at any moment, so a borrow cannot outlive the
    /// lookup. `try_new` runs once per install, not once per URL, so the copy is cheap.
    fn runtime_table(mirror: &Mirror) -> Option<toml::Table> {
        let Mirror::Custom(name) = mirror else {
            return None;
        };
        with_runtime_providers(|providers| providers.get(name.as_str()).cloned())
    }

    /// Build an endpoint table from a runtime provider section.
    fn from_runtime(name: &str, table: &toml::Table) -> Result<Self, MdtError> {
        let field = |f: &str| -> Result<String, MdtError> {
            table
                .get(f)
                .and_then(toml::Value::as_str)
                .map(str::to_string)
                .ok_or_else(|| {
                    MdtError::UnknownProvider(format!(
                        "runtime provider `{name}` is missing field `{f}`"
                    ))
                })
        };
        Ok(Self {
            minecraft: field("minecraft")?,
            fabric: field("fabric")?,
            fabric_maven: field("fabric_maven")?,
            fabric_meta: field("fabric_meta")?,
        })
    }

    /// Build the endpoint table, panicking if the mirror's provider is unknown.
    ///
    /// Convenience wrapper around [`Self::try_new`]; prefer [`Self::try_new`] when the mirror
    /// may be user-supplied.
    #[must_use]
    pub fn new(mirror: &Mirror) -> Self {
        Self::try_new(mirror).expect("mirror provider is not defined in providers.compile.toml")
    }

    /// The Fabric official-installer `profile` endpoint (returns the full version JSON config).
    ///
    /// Path format is `/v2/versions/loader/{game}/{loader}/profile/json`
    /// (game version first, then loader version).
    #[must_use]
    pub fn fabric_profile(&self, loader: &str, game: &str) -> String {
        format!(
            "{}/v2/versions/loader/{}/{}/profile/json",
            self.fabric_meta, game, loader
        )
    }

    /// Rewrite a Mojang download URL through the active mirror.
    ///
    /// The rewrite rules come from the provider's `[[…]].mirror` tables in `providers.compile.toml`,
    /// applied in declaration order. A rule fires only when the URL **starts with** its `from`
    /// prefix (on a URL boundary); a provider with no matching rule — e.g. `mojang` — leaves the URL
    /// unchanged. Nothing is ever substring-replaced.
    #[must_use]
    pub fn apply_mirror(&self, original_url: &str, mirror: &Mirror) -> String {
        if let Mirror::Custom(name) = mirror {
            // A runtime override wins wholesale for a custom mirror: when the table exists, its
            // rules are the only rules applied (a missing rule means "leave the URL alone").
            let runtime = with_runtime_providers(|providers| {
                let table = providers.get(name.as_str())?;
                let rules = runtime_rewrite_rules(table, "mirror");
                Some(
                    rewrite_url(
                        original_url,
                        rules.iter().map(|(from, to)| (from.as_str(), to.as_str())),
                    )
                    .unwrap_or_else(|| original_url.to_string()),
                )
            });
            if let Some(out) = runtime {
                return out;
            }
        }
        match provider_rewrites(mirror.provider_name()) {
            Some(rules) => rewrite_url(original_url, rules.mirror.iter().copied())
                .unwrap_or_else(|| original_url.to_string()),
            None => original_url.to_string(),
        }
    }

    /// Rewrite a Maven repository base URL through the active mirror.
    ///
    /// The rewrite rules come from the provider's `[[…]].maven` tables (applied in declaration
    /// order) and its `maven_exclude` host list in `providers.compile.toml`. A rule fires only on a
    /// host/URL-boundary prefix match; `maven_exclude` is compared against the URL's **host**, not
    /// its text.
    #[must_use]
    pub fn apply_maven_mirror(&self, url: &str, mirror: &Mirror) -> String {
        if let Mirror::Custom(name) = mirror {
            let runtime = with_runtime_providers(|providers| {
                let table = providers.get(name.as_str())?;
                if runtime_string_list(table, "maven_exclude")
                    .iter()
                    .any(|host| host_is_excluded(url, host))
                {
                    return Some(url.to_string());
                }
                let rules = runtime_rewrite_rules(table, "maven");
                Some(
                    rewrite_url(
                        url,
                        rules.iter().map(|(from, to)| (from.as_str(), to.as_str())),
                    )
                    .unwrap_or_else(|| url.to_string()),
                )
            });
            if let Some(out) = runtime {
                return out;
            }
        }
        let Some(rules) = provider_rewrites(mirror.provider_name()) else {
            return url.to_string();
        };
        if rules
            .maven_exclude
            .iter()
            .any(|host| host_is_excluded(url, host))
        {
            return url.to_string();
        }
        rewrite_url(url, rules.maven.iter().copied()).unwrap_or_else(|| url.to_string())
    }

    /// Map a mirrored Maven URL back to the repositories it may have come from.
    ///
    /// The inverse of [`Self::apply_maven_mirror`], used for metadata the mirror may not carry
    /// (e.g. `.sha1` sidecars). Several source repositories can share one mirror base
    /// (`libraries.minecraft.net` and `maven.fabricmc.net` both land in `/bmclapi`), so every
    /// matching rule is returned and the caller can try them in order. An untouched URL yields an
    /// empty list, never a false hit.
    #[must_use]
    pub fn revert_maven_mirror(&self, url: &str, mirror: &Mirror) -> Vec<String> {
        let Some(rules) = provider_rewrites(mirror.provider_name()) else {
            return Vec::new();
        };
        let mut out = Vec::new();
        for (from, to) in rules.maven.iter() {
            let matches = url
                .strip_prefix(to)
                .is_some_and(|rest| rest.starts_with('/') || rest.is_empty());
            if let Some(rest) = url.strip_prefix(to).filter(|_| matches) {
                let candidate = format!("{from}{rest}");
                if !out.contains(&candidate) {
                    out.push(candidate);
                }
            }
        }
        out
    }
}
